/**
 * INC-4417 fixture dataset.
 *
 * Everything the app knows lives here. It is generated by code, but it is
 * *deterministic* code: no Math.random, no Date.now. The same minute always
 * produces the same value, so a tool call made during the demo returns exactly
 * what it returned during development.
 *
 * The jitter below is a hash-based pseudo-noise function, not randomness. It
 * exists so the series look like telemetry instead of step functions; the
 * signal the agent has to find is in the *shape*, not in the noise.
 *
 * Ground truth, for the reader: checkout-service v2.14 (deployed 14:12) cut the
 * HikariCP connection pool from 50 to 10. Threads start queueing for a
 * connection at 14:20 under normal traffic. p99 explodes, p50 barely moves
 * (queueing, not compute), traces pool at `db.connection.acquire`, and the pool
 * logs the timeout. Rolling back dep-1104 fixes it.
 */

export type ServiceId =
  | 'checkout-service'
  | 'payment-gateway'
  | 'inventory-service'
  | 'user-service'
  | 'notification-service';

export type MetricName = 'p50' | 'p99' | 'error_rate';
export type LogLevel = 'debug' | 'info' | 'warn' | 'error';

export const SERVICE_IDS: ServiceId[] = [
  'checkout-service',
  'payment-gateway',
  'inventory-service',
  'user-service',
  'notification-service',
];

/** One-minute resolution. Index 0 === 13:30, index 90 === 15:00. */
export const INCIDENT_DATE = '2026-09-03';
export const T0_ISO = `${INCIDENT_DATE}T13:30:00Z`;
/** "Now" while the incident is live: 15:00. */
export const LIVE_MINUTES = 90;
/** The fixture also holds 20 minutes of post-rollback data, revealed on approval. */
export const TOTAL_MINUTES = 110;

const T0_MS = Date.parse(T0_ISO);

export const isoAtMinute = (i: number): string => new Date(T0_MS + i * 60_000).toISOString();

export const minuteOfIso = (iso: string): number => Math.round((Date.parse(iso) - T0_MS) / 60_000);

/** "2026-09-03T14:20:00.000Z" -> "14:20" */
export const clock = (iso: string): string => iso.slice(11, 16);

// ---------------------------------------------------------------------------
// Deterministic pseudo-noise
// ---------------------------------------------------------------------------

/** Stable hash -> [0, 1). Same inputs, same output, forever. */
function hash01(a: number, b: number): number {
  const x = Math.sin(a * 127.1 + b * 311.7) * 43758.5453123;
  return x - Math.floor(x);
}

/** Stable noise in [-amp, +amp]. */
function wobble(i: number, seed: number, amp: number): number {
  return (hash01(i, seed) * 2 - 1) * amp;
}

/** Deterministic lowercase hex id of `len` chars. */
function hexId(seed: number, len: number): string {
  let out = '';
  for (let k = 0; out.length < len; k++) {
    out += Math.floor(hash01(seed + k * 7.13, 91.7) * 0xffff)
      .toString(16)
      .padStart(4, '0');
  }
  return out.slice(0, len);
}

const round = (v: number, dp = 1): number => {
  const f = 10 ** dp;
  return Math.round(v * f) / f;
};

/** 0 -> 0, 1 -> 1, decelerating. Used for the latency ramp. */
const easeOut = (p: number) => 1 - (1 - p) * (1 - p);

/** Linear ramp from `from` to `to` across [start, start + span] minutes. */
function ramp(i: number, start: number, span: number, from: number, to: number): number {
  if (i <= start) return from;
  if (i >= start + span) return to;
  return from + (to - from) * easeOut((i - start) / span);
}

// ---------------------------------------------------------------------------
// Key moments
// ---------------------------------------------------------------------------

/** Anomaly onset on checkout-service. 14:20. */
export const ANOMALY_START_MINUTE = 50;
/** checkout-service v2.14 ships. 14:12. */
export const ROOT_CAUSE_DEPLOY_MINUTE = 42;
/** Where the rollback lands in the post-mitigation series. 15:03. */
export const ROLLBACK_MINUTE = 93;

// ---------------------------------------------------------------------------
// Metric series
// ---------------------------------------------------------------------------

export interface MetricPoint {
  /** ISO timestamp, minute resolution. */
  t: string;
  v: number;
}

/**
 * p50/p99 are computed over *successful* responses; requests that exhaust the
 * 30s connection timeout are counted in error_rate, not in the latency
 * histogram. That is why p99 plateaus at ~3.4s rather than at the timeout.
 */
function seriesValue(service: ServiceId, metric: MetricName, i: number): number {
  switch (service) {
    case 'checkout-service': {
      // Post-rollback recovery only exists past the live edge.
      const recovering = i >= ROLLBACK_MINUTE;
      if (metric === 'p99') {
        if (recovering) return round(ramp(i, ROLLBACK_MINUTE, 5, 3400, 184) + wobble(i, 3, 12), 1);
        return round(ramp(i, ANOMALY_START_MINUTE - 1, 5, 181, 3400) + wobble(i, 3, i < ANOMALY_START_MINUTE ? 14 : 110), 1);
      }
      if (metric === 'p50') {
        if (recovering) return round(ramp(i, ROLLBACK_MINUTE, 5, 78, 62) + wobble(i, 5, 3), 1);
        return round(ramp(i, ANOMALY_START_MINUTE - 1, 5, 62, 78) + wobble(i, 5, 4), 1);
      }
      if (recovering) return round(Math.max(0.02, ramp(i, ROLLBACK_MINUTE, 4, 4.2, 0.11) + wobble(i, 7, 0.05)), 2);
      return round(
        Math.max(0.02, ramp(i, ANOMALY_START_MINUTE - 1, 7, 0.1, 4.2) + wobble(i, 7, i < ANOMALY_START_MINUTE ? 0.04 : 0.18)),
        2,
      );
    }

    case 'payment-gateway': {
      // Downstream victim: checkout holds payment sessions open longer.
      const recovering = i >= ROLLBACK_MINUTE;
      const onset = ANOMALY_START_MINUTE + 2;
      if (metric === 'p99') {
        if (recovering) return round(ramp(i, ROLLBACK_MINUTE, 5, 520, 243) + wobble(i, 11, 16), 1);
        return round(ramp(i, onset, 6, 241, 520) + wobble(i, 11, i < onset ? 18 : 30), 1);
      }
      if (metric === 'p50') {
        if (recovering) return round(ramp(i, ROLLBACK_MINUTE, 5, 104, 88) + wobble(i, 13, 4), 1);
        return round(ramp(i, onset, 6, 88, 104) + wobble(i, 13, 5), 1);
      }
      if (recovering) return round(Math.max(0.02, ramp(i, ROLLBACK_MINUTE, 4, 0.9, 0.21) + wobble(i, 17, 0.05)), 2);
      return round(Math.max(0.02, ramp(i, onset + 2, 5, 0.2, 0.9) + wobble(i, 17, 0.06)), 2);
    }

    case 'inventory-service': {
      // Red herring: a cache-TTL deploy at 13:44 causes a bump that self-resolves.
      const bump = (peak: number, base: number) => {
        if (i < 15 || i > 24) return base;
        const up = ramp(i, 15, 3, base, peak);
        const down = ramp(i, 20, 4, peak, base);
        return i <= 19 ? up : down;
      };
      if (metric === 'p99') return round(bump(431, 151) + wobble(i, 19, 12), 1);
      if (metric === 'p50') return round(bump(58, 44) + wobble(i, 23, 3), 1);
      return round(Math.max(0.02, bump(0.45, 0.1) + wobble(i, 29, 0.05)), 2);
    }

    case 'user-service': {
      if (metric === 'p99') return round(95 + wobble(i, 31, 8), 1);
      if (metric === 'p50') return round(31 + wobble(i, 37, 3), 1);
      return round(Math.max(0.01, 0.05 + wobble(i, 41, 0.03)), 2);
    }

    case 'notification-service': {
      // Chronically noisy but stable: stops "highest error rate" being a giveaway.
      if (metric === 'p99') return round(211 + wobble(i, 43, 16), 1);
      if (metric === 'p50') return round(58 + wobble(i, 47, 4), 1);
      return round(Math.max(0.05, 0.31 + wobble(i, 53, 0.08)), 2);
    }
  }
}

const buildSeries = (): Record<ServiceId, Record<MetricName, MetricPoint[]>> => {
  const out = {} as Record<ServiceId, Record<MetricName, MetricPoint[]>>;
  for (const service of SERVICE_IDS) {
    out[service] = { p50: [], p99: [], error_rate: [] };
    for (const metric of ['p50', 'p99', 'error_rate'] as MetricName[]) {
      for (let i = 0; i <= TOTAL_MINUTES; i++) {
        out[service][metric].push({ t: isoAtMinute(i), v: seriesValue(service, metric, i) });
      }
    }
  }
  return out;
};

export const SERIES = buildSeries();

export const METRIC_UNITS: Record<MetricName, string> = {
  p50: 'ms',
  p99: 'ms',
  error_rate: '%',
};

export const METRIC_LABELS: Record<MetricName, string> = {
  p50: 'p50 latency',
  p99: 'p99 latency',
  error_rate: 'error rate',
};

