// ---------------------------------------------------------------------------
// Traces
// ---------------------------------------------------------------------------

export interface Span {
  name: string;
  durationMs: number;
  /** Set when the span is a call into another service. */
  peer?: ServiceId;
}

export interface Trace {
  id: string;
  service: ServiceId;
  operation: string;
  t: string;
  durationMs: number;
  status: 'ok' | 'error';
  /** Non-overlapping child spans. durationMs === sum(spans) + root overhead. */
  spans: Span[];
  error?: string;
}

function checkoutSpans(i: number, kind: 'pre' | 'ramp' | 'post' | 'timeout'): Span[] {
  const acquire =
    kind === 'pre'
      ? 3 + wobble(i, 61, 1.4)
      : kind === 'ramp'
        ? ramp(i, ANOMALY_START_MINUTE - 1, 5, 3, 3050) + wobble(i, 61, 90)
        : kind === 'timeout'
          ? 30000
          : 3050 + wobble(i, 61, 190);
  const payment = kind === 'pre' ? 71 + wobble(i, 67, 12) : 128 + wobble(i, 67, 21);
  return [
    { name: 'auth.verify', durationMs: round(11 + wobble(i, 59, 2), 1) },
    { name: 'db.connection.acquire', durationMs: round(Math.max(0.4, acquire), 1) },
    { name: 'db.query cart_items', durationMs: round(48 + wobble(i, 63, 8), 1) },
    { name: 'inventory.check', durationMs: round(34 + wobble(i, 65, 6), 1), peer: 'inventory-service' },
    { name: 'payment.authorize', durationMs: round(payment, 1), peer: 'payment-gateway' },
    ...(kind === 'timeout' ? [] : [{ name: 'db.query order_insert', durationMs: round(22 + wobble(i, 69, 4), 1) }]),
  ];
}

function makeTrace(
  service: ServiceId,
  operation: string,
  minute: number,
  spans: Span[],
  status: 'ok' | 'error' = 'ok',
  error?: string,
): Trace {
  const sum = spans.reduce((a, s) => a + s.durationMs, 0);
  const overhead = round(1.2 + wobble(minute, 71, 0.6), 1);
  return {
    id: `tr-${hexId(minute + spans.length * 3.7 + service.length, 12)}`,
    service,
    operation,
    t: isoAtMinute(minute),
    durationMs: round(sum + overhead, 1),
    status,
    spans,
    error,
  };
}

function buildTraces(): Trace[] {
  const out: Trace[] = [];

  const pre = [2, 6, 9, 13, 17, 21, 24, 28, 31, 35, 38, 41, 44, 46, 48];
  const rampMinutes = [50, 51, 52, 53];
  const post = [55, 57, 58, 60, 62, 63, 65, 67, 68, 70, 72, 74, 76, 78, 80, 82, 84, 86, 88, 89];
  const timeouts = [61, 71, 83];

  for (const m of pre) out.push(makeTrace('checkout-service', 'POST /api/v1/checkout', m, checkoutSpans(m, 'pre')));
  for (const m of rampMinutes) out.push(makeTrace('checkout-service', 'POST /api/v1/checkout', m, checkoutSpans(m, 'ramp')));
  for (const m of post) out.push(makeTrace('checkout-service', 'POST /api/v1/checkout', m, checkoutSpans(m, 'post')));
  for (const m of timeouts) {
    out.push(
      makeTrace(
        'checkout-service',
        'POST /api/v1/checkout',
        m,
        checkoutSpans(m, 'timeout'),
        'error',
        'SQLTransientConnectionException: HikariPool-1 - Connection is not available, request timed out after 30000ms',
      ),
    );
  }

  for (const m of [5, 19, 33, 47, 56, 64, 73, 81, 87]) {
    const slow = m >= 52;
    out.push(
      makeTrace('payment-gateway', 'POST /v2/authorize', m, [
        { name: 'risk.score', durationMs: round(28 + wobble(m, 73, 5), 1) },
        { name: 'psp.dispatch', durationMs: round((slow ? 168 : 92) + wobble(m, 79, slow ? 24 : 11), 1) },
        { name: 'db.query auth_log', durationMs: round(19 + wobble(m, 83, 4), 1) },
      ]),
    );
  }

  for (const m of [16, 18, 20, 22, 40, 66]) {
    const cold = m >= 15 && m <= 24;
    out.push(
      makeTrace('inventory-service', 'GET /v1/stock', m, [
        { name: 'cache.lookup', durationMs: round((cold ? 4 : 2) + wobble(m, 89, 1), 1) },
        { name: 'db.query stock_levels', durationMs: round((cold ? 288 : 41) + wobble(m, 97, cold ? 22 : 6), 1) },
      ]),
    );
  }

  for (const m of [30, 59, 85]) {
    out.push(
      makeTrace('user-service', 'GET /v1/profile', m, [
        { name: 'db.query users', durationMs: round(37 + wobble(m, 101, 6), 1) },
        { name: 'serialize', durationMs: round(6 + wobble(m, 103, 1.5), 1) },
      ]),
    );
  }

  return out.sort((a, b) => a.t.localeCompare(b.t));
}

export const TRACES: Trace[] = buildTraces();

// ---------------------------------------------------------------------------
// Logs
// ---------------------------------------------------------------------------

export interface LogLine {
  id: string;
  t: string;
  service: ServiceId;
  level: LogLevel;
  message: string;
}

function buildLogs(): LogLine[] {
  const out: Omit<LogLine, 'id'>[] = [];
  const push = (minute: number, service: ServiceId, level: LogLevel, message: string) =>
    out.push({ t: isoAtMinute(minute), service, level, message });

  // --- Baseline chatter, both before and after the anomaly -----------------
  for (let m = 0; m <= LIVE_MINUTES; m += 4) {
    push(m, 'checkout-service', 'info', `Checkout completed order=ord-${hexId(m, 8)} in ${Math.round(seriesValue('checkout-service', 'p50', m))}ms`);
  }
  for (let m = 3; m <= LIVE_MINUTES; m += 8) {
    push(m, 'notification-service', 'warn', 'Retrying webhook delivery attempt=2 endpoint=https://hooks.partner.example/orders');
  }
  for (let m = 7; m <= LIVE_MINUTES; m += 12) {
    push(m, 'notification-service', 'info', `Digest batch flushed size=${180 + Math.round(hash01(m, 109) * 90)}`);
  }
  for (let m = 4; m <= LIVE_MINUTES; m += 6) {
    push(m, 'user-service', 'info', `Session refreshed subject=usr-${hexId(m + 4, 6)}`);
  }
  for (let m = 8; m <= LIVE_MINUTES; m += 7) {
    push(m, 'payment-gateway', 'info', `Authorization approved psp=stripe latency=${Math.round(seriesValue('payment-gateway', 'p50', m))}ms`);
  }
  for (let m = 5; m <= LIVE_MINUTES; m += 10) {
    push(m, 'inventory-service', 'info', `Stock lookup batch sku_count=${20 + Math.round(hash01(m, 113) * 60)}`);
  }

  // --- Red herring: inventory cold cache after dep-1091 --------------------
  push(14, 'inventory-service', 'info', 'Deployment complete: inventory-service v1.9 (dep-1091)');
  for (const m of [15, 16, 17, 18, 19, 20]) {
    push(m, 'inventory-service', 'warn', 'Stock cache miss ratio 0.71 above threshold 0.30 - warming');
  }
  push(24, 'inventory-service', 'info', 'Stock cache miss ratio 0.06 - back within threshold');

  // --- The root cause deploy ----------------------------------------------
  push(42, 'checkout-service', 'info', 'Deployment complete: checkout-service v2.14 (dep-1104)');
  push(42, 'checkout-service', 'info', 'HikariPool-1 - Starting... maximumPoolSize=10 connectionTimeout=30000');
  push(43, 'checkout-service', 'info', 'HikariPool-1 - Start completed.');

  // --- Saturation builds quietly before the alert fires --------------------
  for (const m of [46, 48]) {
    push(m, 'checkout-service', 'debug', 'HikariPool-1 - Pool stats (total=10, active=9, idle=1, waiting=0)');
  }

  // --- The tell, repeated -------------------------------------------------
  for (const m of [50, 52, 54, 56, 58, 61, 64, 66, 69, 71, 74, 77, 79, 82, 83, 86, 88, 90]) {
    push(m, 'checkout-service', 'error', 'HikariPool-1 - Connection is not available, request timed out after 30000ms');
  }
  for (const m of [51, 55, 59, 63, 67, 72, 76, 81, 85, 89]) {
    const waiting = 12 + Math.round(hash01(m, 107) * 26);
    push(m, 'checkout-service', 'warn', `HikariPool-1 - Timeout failure stats (total=10, active=10, idle=0, waiting=${waiting})`);
  }
  for (const m of [53, 60, 68, 75, 84]) {
    push(m, 'checkout-service', 'error', 'Order submission failed: SQLTransientConnectionException acquiring connection for order_insert');
  }

  // --- Downstream noise ----------------------------------------------------
  for (const m of [57, 65, 73, 80, 87]) {
    push(m, 'payment-gateway', 'warn', 'Authorization session held open beyond 2000ms by upstream checkout-service');
  }
  push(85, 'user-service', 'info', 'Deployment complete: user-service v3.2 (dep-1112)');
  push(86, 'user-service', 'info', 'Route registered: GET /v2/profile');

  return out
    .sort((a, b) => a.t.localeCompare(b.t))
    .map((l, idx) => ({ ...l, id: `log-${idx.toString().padStart(4, '0')}` }));
}

